    defined.rejected.join(" "),
  ].filter(Boolean);
  const fences = [...content.matchAll(/^[ \t]*```([^\r\n`]*)\r?\n([\s\S]*?)\r?\n[ \t]*```[ \t]*(?=\r?\n|$)/gm)];
