  }
  const canvasSpecs: Spec[] = [];
  const prose: string[] = [];
  let cursor = 0;
  let rejected = false;
  const blocks = fences.length ? fences : [{ 0: content, 1: "spec", 2: content.trim(), index: 0 }];
  for (const [index, block] of blocks.entries()) {
    const at = block.index!;
160→    prose.push(content.slice(cursor, at));
