/* The canvas owns the viewport. Chat and tools float above it without reserving columns. */
html, body, #root { height: 100%; }
body { margin: 0; }
.svelte-chat-app {
  --sc-bg: #111113;
  --sc-panel: #19191c;
  --sc-line: #303035;
  --sc-muted: #a1a1aa;
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: var(--sc-bg);
  color: #f4f4f5;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
  line-height: 1.6;
}
.svelte-chat-app *, .svelte-chat-app *::before, .svelte-chat-app *::after { box-sizing: border-box; }
.svelte-chat-app [hidden] { display: none !important; }
.svelte-chat-app button, .svelte-chat-app textarea { font: inherit; }
.svelte-chat-app button { cursor: pointer; }
.svelte-chat-app button:disabled { opacity: .45; cursor: not-allowed; }
.svelte-chat-app :focus-visible { outline: 2px solid #c4b5fd; outline-offset: 4px; }
.sc-canvas { position: absolute; inset: 0; width: 100%; height: 100%; overflow: auto; margin: 0; padding: 0; }
.sc-header { position: absolute; z-index: 30; top: max(12px, env(safe-area-inset-top)); left: max(12px, env(safe-area-inset-left)); display: flex; align-items: center; gap: 14px; padding: 6px 10px 6px 14px; border: 1px solid var(--sc-line); border-radius: 12px; background: #19191cf5; box-shadow: 0 6px 24px #0005; }
.sc-brand, .sc-header-actions { display: flex; align-items: center; gap: 10px; }
.sc-brand h1 { margin: 0; font-size: 17px; letter-spacing: -.5px; font-weight: 650; }
.sc-connection { display: flex; align-items: center; gap: 7px; color: var(--sc-muted); font-size: 11px; }
.sc-connection i { width: 6px; height: 6px; border-radius: 50%; background: #a7bca0; }
.sc-button { border: 1px solid transparent; border-radius: 7px; background: transparent; padding: 6px 10px; color: var(--sc-muted); font-size: 12px; }
.sc-button:hover, .sc-button[aria-expanded="true"] { background: #29292e; color: #fafafa; }
.sc-chat-pane { position: absolute; z-index: 20; left: max(12px, env(safe-area-inset-left)); top: calc(max(12px, env(safe-area-inset-top)) + 58px); bottom: max(12px, env(safe-area-inset-bottom)); width: min(410px, calc(100vw - 24px)); display: flex; flex-direction: column; min-height: 0; overflow: hidden; border: 1px solid var(--sc-line); border-radius: 14px; background: #111113fa; box-shadow: 0 12px 40px #0006; }
.sc-pane-heading { display: flex; align-items: center; gap: 6px; padding: 10px 12px; flex-shrink: 0; border-bottom: 1px solid var(--sc-line); }
.sc-pane-heading h2 { flex: 1; margin: 0; font-size: 14px; }
.sc-pane-controls { max-height: 35%; flex-shrink: 0; overflow: auto; border-bottom: 1px solid var(--sc-line); padding: 10px 12px; }
.sc-pane-controls .routing-strip, .sc-pane-controls .mode-strip { margin: 0; padding: 8px 0; min-width: 0; }
.sc-pane-controls select { max-width: 100%; }
.sc-settings { padding-bottom: 8px; }
.sc-knowledge:empty { display: none; }
.sc-knowledge { max-height: 18dvh; overflow: auto; }
.sc-conversation { flex: 1; display: flex; flex-direction: column; min-width: 0; min-height: 0; position: relative; }
.sc-thread-toolbar { padding: 8px 14px; min-height: 36px; display: flex; align-items: center; justify-content: space-between; color: var(--sc-muted); font-size: 11px; gap: 8px; }
.sc-thread-toolbar > span { overflow-wrap: anywhere; }
.sc-messages { flex: 1; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-color: #3c3c43 transparent; }
