.svelte-chat-app button, .svelte-chat-app textarea { font: inherit; }
.svelte-chat-app button { cursor: pointer; }
.svelte-chat-app button:disabled { opacity: .45; cursor: not-allowed; }
.svelte-chat-app :focus-visible { outline: 2px solid #c4b5fd; outline-offset: 4px; }
.sc-canvas { position: absolute; inset: 0; width: 100%; height: 100%; overflow: auto; margin: 0; padding: 0; }
