.sc-brand, .sc-header-actions { display: flex; align-items: center; gap: 10px; }
.sc-brand h1 { margin: 0; font-size: 17px; letter-spacing: -.5px; font-weight: 650; }
.sc-connection { display: flex; align-items: center; gap: 7px; color: var(--sc-muted); font-size: 11px; }
.sc-connection i { width: 6px; height: 6px; border-radius: 50%; background: #a7bca0; }
.sc-button { border: 1px solid transparent; border-radius: 7px; background: transparent; padding: 6px 10px; color: var(--sc-muted); font-size: 12px; }
.sc-button:hover, .sc-button[aria-expanded="true"] { background: #29292e; color: #fafafa; }
.sc-chat-pane { position: absolute; z-index: 20; left: max(12px, env(safe-area-inset-left)); top: calc(max(12px, env(safe-area-inset-top)) + 58px); bottom: max(12px, env(safe-area-inset-bottom)); width: min(410px, calc(100vw - 24px)); display: flex; flex-direction: column; min-height: 0; overflow: hidden; border: 1px solid var(--sc-line); border-radius: 14px; background: #111113fa; box-shadow: 0 12px 40px #0006; }
.sc-pane-heading { display: flex; align-items: center; gap: 6px; padding: 10px 12px; flex-shrink: 0; border-bottom: 1px solid var(--sc-line); }
.sc-pane-heading h2 { flex: 1; margin: 0; font-size: 14px; }
.sc-pane-controls { max-height: 35%; flex-shrink: 0; overflow: auto; border-bottom: 1px solid var(--sc-line); padding: 10px 12px; }
.sc-pane-controls .routing-strip, .sc-pane-controls .mode-strip { margin: 0; padding: 8px 0; min-width: 0; }
.sc-pane-controls select { max-width: 100%; }
.sc-settings { padding-bottom: 8px; }
.sc-knowledge:empty { display: none; }
